SELECT f.object_key FROM case_files f JOIN cases c ON c.id=f.case_id JOIN proof_backups b ON b.file_id=f.id AND b.provider='google_drive' AND b.status='confirmed' LEFT JOIN cold_proofs p ON p.file_id=f.id WHERE c.status IN('completed','rejected','revoked') AND c.reviewed_at IS NOT NULL AND julianday(coalesce(c.status_updated_at,c.updated_at))<=julianday('now','-7 days') AND (p.file_id IS NULL OR p.state='dry_run' OR (p.state='blocked' AND p.updated_at<?) OR (p.state='verifying' AND p.lease_until<?)) AND coalesce(p.state,'')!='deleting' ORDER BY CASE WHEN p.verification_context IS NOT NULL THEN 0 ELSE 1 END,coalesce(c.status_updated_at,c.updated_at),f.id LIMIT 1;
